// About: the guide, the changes, credits and the licence, bundled with the
// app (no network). Main view: the chosen document. Panel: the documents and
// each one's chapters (a click jumps to it).
import { BookOpen, FileText, History, Scale } from "lucide-react";
import Markdown from "react-markdown";
import remarkGfm from "remark-gfm";
import guide from "../../../docs/GUIDE.md?raw";
import changelog from "../../../CHANGELOG.md?raw";
import credits from "../../../docs/CREDITS.md?raw";
// generated by tools/gen_notices.mjs (LICENSE §6); also shipped as a file in the app's resources (electron-builder.yml)
import notices from "../../../THIRD_PARTY_NOTICES.md?raw";
import { Accordion, Section, type SectionFocus } from "../panel/Section";
import { SplitView } from "../panel/SplitView";
import { usePref } from "../prefs";
import { versionText } from "./SettingsPage";

const DOCS = {
  guide: { title: "Guide", icon: BookOpen, text: guide },
  changes: { title: "Changes", icon: History, text: changelog },
  credits: { title: "Credits & licence", icon: Scale, text: credits },
  notices: { title: "Third-party notices", icon: FileText, text: notices },
} as const;
type DocId = keyof typeof DOCS;

const slug = (s: string) =>
  s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
/** A heading's text as written in the doc ("## Title" → "Title"), from its place in the source. */
const headingSource = (md: string, start = 0, end = 0) =>
  md
    .slice(start, end)
    .replace(/^##\s+/, "")
    .trim();
// loop: NOT-WORTH — a doc's chapter headings (≤ 20), per render of the About page
const chapters = (md: string) => [...md.matchAll(/^##\s+(.+)$/gm)].map((m) => m[1].trim());

export function AboutPage(props: { version: string; panelShown: boolean; narrow: boolean; glass: boolean; focus: SectionFocus; hidePanel: () => void }) {
  const [doc, setDoc] = usePref<DocId>("ck.about.doc", "guide");
  const d = DOCS[doc] ?? DOCS.guide;

  const main = (
    <div className="page-body">
      <div className="page-bar">
        <h1>About</h1>
        <span className="spacer" />
        <span className="chip">CorridorKey Desktop {versionText(props.version)}</span>
      </div>
      <article className="page-content doc">
        <Markdown
          remarkPlugins={[remarkGfm]}
          components={{
            // the id from the heading's own source line, as chapters() reads it (String(children) of a heading with
            // `code` or a link was "[object Object]", so its chapter never scrolled)
            h2: ({ node, children }) => <h2 id={slug(headingSource(d.text, node?.position?.start.offset, node?.position?.end.offset))}>{children}</h2>,
            a: ({ href, children }) => (
              <a href={href} target="_blank" rel="noreferrer">
                {children}
              </a>
            ),
          }}
        >
          {d.text}
        </Markdown>
      </article>
    </div>
  );

  const panel = (
    <Accordion page="about" focus={props.focus}>
      {/* loop: NOT-WORTH — four docs per render */}
      {(Object.keys(DOCS) as DocId[]).map((id) => (
        <Section key={id} id={id} icon={DOCS[id].icon} title={DOCS[id].title} status={id === doc ? "Shown" : "Click a chapter to read it"}>
          {() => (
            <ul className="chapters">
              {/* loop: NOT-WORTH — a doc's chapters (≤ 20) per render */}
              {chapters(DOCS[id].text).map((h) => (
                <li key={h}>
                  <button
                    type="button"
                    className="link-btn"
                    onClick={() => {
                      setDoc(id);
                      // loop: NOT-WORTH — one rAF per chapter click (scroll after the page switch)
                      requestAnimationFrame(() => document.getElementById(slug(h))?.scrollIntoView({ behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth" }));
                    }}
                  >
                    {h}
                  </button>
                </li>
              ))}
              {chapters(DOCS[id].text).length === 0 && (
                <li>
                  <button type="button" className="link-btn" onClick={() => setDoc(id)}>
                    Open
                  </button>
                </li>
              )}
            </ul>
          )}
        </Section>
      ))}
    </Accordion>
  );

  return <SplitView main={main} panel={panel} panelTitle="About" panelSub={d.title} shown={props.panelShown} narrow={props.narrow} glass={props.glass} onEscape={props.hidePanel} />;
}
